288,rotki,rotkelchen/binance.py,157892b592488df4a39b0a04e5916a40559a746a,157892b592488df4a39b0a04e5916a40559a746a,accepted,YES,,accepted,1,NO,False,#TODO: in progress,context_required,context_required,True,1.0,forced_route:context_required,,0.018962931709871487,0.015811494798397434,0.08695652173913045,0.0,pass,True,method_context_prepared,,,identified_methods=1; retrieved_methods=1,method_context,0,0,0,api_query,Binance.api_query,,1,"[{""method_name"": ""Binance.api_query"", ""path"": ""rotkelchen/binance.py"", ""class_name"": ""Binance"", ""start_line"": 33, ""end_line"": 65, ""source"": ""def api_query(self, method, options=None):
        if not options:
            options = {}

        if method in V3_ENDPOINTS:
            api_version = 3
        elif method in V1_ENDPOINTS:
            api_version = 1
        else:
            raise ValueError('Unexpected binance api method {}'.format(method))

        options['timestamp'] = str(int(time.time() * 1000))
        request_url = self.uri + '/v' + str(api_version) + '/' + method + '?'
        signature = hmac.new(
            self.secret,
            urlencode(options).encode(),
            hashlib.sha256
        ).hexdigest()
        headers = {'X-MBX-APIKEY': self.api_key}
        options['signature'] = signature
        request_url += urlencode(options)
        try:
            ret = urlopen(Request(request_url, headers=headers))
        except HTTPError as e:
            print('Binance API request for {} failed with {} {}'.format(
                method,
                e.code,
                e.msg
            ))
            return {}

        json_ret = rlk_jsonloads(ret.read())
        return json_ret"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}]",[],[],True,accept,"def query_trade_history(self, start_ts=None, end_ts=None, end_at_least_ts=None):

